using System.Linq;using NUnit.Framework;using UnityEditor.SceneManagement;using UnityEngine;using EternalSteam.OpenWorld;
namespace EternalSteam.Tests{
[Category("CurrentScene")]
public sealed class RailwayEditorPanelTests{
[Test]

public void EditorCommandsAndPagesAreAuthored(){var scene=CurrentSceneFixture.Open();var name=scene.name;try{var h=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CanvasWorldHud>(true)).Single();var v=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>();var e=v.Editor;Assert.That(e,Is.Not.Null);Assert.That(e.Overview,Is.SameAs(v));Assert.That(e.Root.IsChildOf(v.Root),Is.True);Assert.That(e.Bindings.Length,Is.EqualTo(37));Assert.That(e.Bindings.Select(b=>b.Command).Distinct().Count(),Is.EqualTo(e.Bindings.Length));foreach(var b in e.Bindings){Assert.That(b.Source,Is.Not.Null);Assert.That(b.Button.onClick.GetPersistentTarget(0),Is.SameAs(e));Assert.That(b.Button.onClick.GetPersistentMethodName(0),Is.EqualTo("Execute"));Assert.That(v.Railway.Commands.Any(c=>c.Command==b.Command&&c.Button==b.Source),Is.True);}foreach(var tab in new[]{e.Stations,e.Diagnostics}){Assert.That(tab.onClick.GetPersistentTarget(0),Is.SameAs(e));Assert.That(tab.onClick.GetPersistentMethodName(0),Is.EqualTo("SelectPage"));}Assert.That(e.Scroll.GetComponent<UnityEngine.UI.ScrollRect>().content,Is.SameAs(e.Content));Assert.That(e.Scroll.GetComponent<UnityEngine.UI.ScrollRect>().viewport.GetComponent<UnityEngine.UI.Mask>(),Is.Not.Null);Assert.That(e.Root.GetComponentsInChildren<TMPro.TMP_Text>(true).All(t=>t.fontSize==18&&!t.enableAutoSizing),Is.True);foreach(var b in e.Bindings.Where(b=>b.Footer))Assert.That(b.Button.transform.IsChildOf(e.Scroll),Is.False,"Commit/cancel remain outside scrolling");}finally{CurrentSceneFixture.Close(scene);}}
}}
